<header class="admin-header"><div><p class="kicker">Leads</p><h1>Mensajes</h1><p>Consultas y suscripciones recibidas desde el sitio.</p></div></header>
<nav class="filter-tabs" aria-label="Filtrar mensajes"><a href="<?= e(url('/admin/mensajes')) ?>" <?= !$type ? 'aria-current="page"' : '' ?>>Todos</a><a href="<?= e(url('/admin/mensajes?type=contact')) ?>" <?= $type === 'contact' ? 'aria-current="page"' : '' ?>>Contacto</a><a href="<?= e(url('/admin/mensajes?type=newsletter')) ?>" <?= $type === 'newsletter' ? 'aria-current="page"' : '' ?>>Newsletter</a></nav>
